import"./main-Ctl3c-dT.js";var e=document.getElementById(`valor1`),t=document.getElementById(`valor2`),n=document.getElementById(`resultado`),r=document.getElementById(`calculadora`);function i(e,t){return e+t}function a(e,t){return e-t}function o(e,t){return e*t}function s(e,t){return e/t}r.addEventListener(`submit`,c=>{if(c.preventDefault(),e.value&&t.value){let l=Number(e.value),u=Number(t.value);if(c.submitter)switch(c.submitter.id){case`sumar`:n.innerText=`El resultado es: ${i(l,u)}`,r.reset();break;case`restar`:n.innerText=`El resultado es: ${a(l,u)}`,r.reset();break;case`multiplicar`:n.innerText=`El resultado es: ${o(l,u)}`,r.reset();break;case`dividir`:u>0?(n.innerText=`El resultado es: ${s(l,u)}`,r.reset()):n.textContent=`No es posible dividir entre "0"`}}});